local function murloc(ctx,e)for _,t in ipairs(ctx:card_definition(ctx:entity(e).card_id).tags)do if t=="murloc"or t=="all"then return true end end return false end
return {api_version=1,id="EX1_103",name="Coldlight Seer",text="<b>Battlecry:</b> Give your other Murlocs +2 Health.",set="EXPERT1",type="minion",rarity="rare",cost=3,attack=2,health=3,tags={"murloc"},keywords={"battlecry"},on_battlecry=function(ctx,self)for _,e in ipairs(ctx:friendly_minions(self))do if e~=self and murloc(ctx,e)then ctx:buff(e,0,2)end end end}
